CustomField.formula:
IF ( 
ISPICKVAL ( Sub_Type__c , "FOC Qantas Club Waiver") , 
DATE( Year( Campaign_Start_Date__c )+floor((MONTH( Campaign_Start_Date__c) + 1 - 1) / 12) , 
mod(MONTH(Campaign_Start_Date__c) + 1 -1, 12) + 1 , 
day(Campaign_Start_Date__c) 
) - 1 , 
IF ( NOT(ISNULL (Override_Date__c)), Override_Date__c, 

DATE( Year( Campaign_Start_Date__c )+floor((MONTH( Campaign_Start_Date__c) + 3 - 1) / 12) , 
mod(MONTH(Campaign_Start_Date__c) + 3 -1, 12) + 1 , 
day(Campaign_Start_Date__c) 
) - 1

)
)
